ALLOWED_IMAGE_EXTS = {"jpg", "jpeg", "png", "webp"}
DEFAULT_ADMIN_USERNAME = os.environ.get("PJ_ADMIN_USERNAME", "admin")
DEFAULT_ADMIN_PASSWORD = os.environ.get("PJ_ADMIN_PASSWORD", "PJadmin123!")

