BASE = r"""<!doctype html>
<html lang="th">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<link rel="icon" href="{{ logo_url }}">
<title>{% block title %}พีเจกันพลา{% endblock %}</title>

<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Kanit:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">

<style>
:root{
  --navy:#111827;
  --navy-2:#1f2937;
  --blue:#2563eb;
  --blue-2:#1d4ed8;
  --cyan:#00a9e8;
  --red:#e53935;
  --yellow:#f7c948;
  --green:#16a34a;
  --bg:#f4f6f8;
  --card:#ffffff;
  --line:#e4e8ee;
  --text:#222b36;
  --muted:#718096;
  --max:1220px;
}

*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  background:var(--bg);
  color:var(--text);
  font-family:"Kanit",system-ui,sans-serif;
  line-height:1.6;
}
a{color:inherit}
button,input,select,textarea{font:inherit}

.main-head .wrap,
.breadcrumb .wrap,
.page .wrap,
.footer .wrap{
  max-width:var(--max);
  margin:auto;
  padding-left:20px;
  padding-right:20px;
}

.main-head{
  background:#fff;
  border-bottom:1px solid var(--line);
}
.main-head .wrap{
  min-height:74px;
  display:flex;
  align-items:center;
  gap:18px;
}
.logo{
  text-decoration:none;
  font-size:1.65rem;
  font-weight:800;
  white-space:nowrap;
  letter-spacing:.01em;
}
.logo{display:flex;align-items:center;gap:10px}
.logo-img{width:48px;height:48px;object-fit:contain;flex:none}
.logo-img.round{border-radius:50%}
.logo span{color:var(--blue)}
.logo small{
  display:block;
  color:var(--muted);
  font-size:.67rem;
  font-weight:500;
  margin-top:-6px;
}
.search{
  flex:1;
  display:flex;
  max-width:670px;
  margin:auto;
}
.search input{
  width:100%;
  height:42px;
  border:1px solid #cfd7e3;
  border-right:0;
  border-radius:7px 0 0 7px;
  padding:0 14px;
  outline:none;
  background:#fff;
}
.search input:focus{border-color:var(--blue)}
.search button{
  width:52px;
  border:0;
  background:var(--blue);
  color:#fff;
  border-radius:0 7px 7px 0;
  cursor:pointer;
}
.head-actions{
  display:flex;
  gap:8px;
  align-items:center;
  white-space:nowrap;
}
.head-actions a{
  text-decoration:none;
  padding:7px 10px;
  border-radius:6px;
}
.head-actions a:hover{background:#f0f4f8}

.category-nav{
  background:var(--navy);
  color:#fff;
}
.category-nav .wrap{
  max-width:var(--max);
  margin:auto;
  padding:0 20px;
  min-height:44px;
  display:flex;
  align-items:center;
  gap:4px;
  overflow-x:auto;
}
.category-nav a{
  padding:10px 14px;
  text-decoration:none;
  font-size:.93rem;
  white-space:nowrap;
}
.category-nav a:hover,
.category-nav a.active{background:#273449}

.hero{
  max-width:var(--max);
  margin:20px auto 0;
  padding:0 20px;
}
.hero-box{
  min-height:225px;
  border-radius:12px;
  overflow:hidden;
  position:relative;
  display:flex;
  align-items:center;
  padding:32px;
  color:#fff;
  background:
    radial-gradient(circle at 83% 20%,rgba(0,169,232,.36),transparent 30%),
    radial-gradient(circle at 90% 90%,rgba(37,99,235,.28),transparent 32%),
    linear-gradient(135deg,#0a0f18,#1e293b 58%,#0f4c81);
  box-shadow:0 12px 28px rgba(15,23,42,.12);
}
.hero-box:after{
  content:"";
  position:absolute;
  width:300px;
  height:300px;
  right:-70px;
  top:-60px;
  border:30px solid rgba(255,255,255,.07);
  transform:rotate(20deg);
  border-radius:28px;
}
.hero-content{position:relative;z-index:1;max-width:650px}
.hero-logo{
  position:absolute;right:56px;top:50%;transform:translateY(-50%);
  width:185px;height:185px;object-fit:contain;z-index:1;
  filter:drop-shadow(0 8px 22px rgba(0,0,0,.45));
}
.hero-logo.round{border-radius:50%;box-shadow:0 0 0 4px rgba(255,255,255,.10),0 12px 38px rgba(37,99,235,.45)}
@media (max-width:960px){
  .hero-box{flex-direction:column;align-items:flex-start}
  .hero-logo{position:static;transform:none;width:112px;height:112px;margin-top:16px}
}
.hero-kicker{
  color:#8edcff;
  font-weight:700;
  letter-spacing:.08em;
  text-transform:uppercase;
  font-size:.86rem;
}
.hero h1{
  font-size:2.25rem;
  margin:4px 0;
  line-height:1.15;
}
.hero p{margin:10px 0 18px;color:#dce9f5}
.hero-buttons{display:flex;gap:9px;flex-wrap:wrap}
.btn{
  display:inline-flex;
  justify-content:center;
  align-items:center;
  min-height:40px;
  padding:8px 16px;
  border:0;
  border-radius:6px;
  text-decoration:none;
  cursor:pointer;
  font-weight:600;
}
.btn-primary{background:var(--blue);color:#fff}
.btn-primary:hover{background:var(--blue-2)}
.btn-dark{background:#243142;color:#fff}
.btn-danger{background:var(--red);color:#fff}
.btn-muted{background:#a4adba;color:#fff;cursor:not-allowed}

.page{padding-top:20px;padding-bottom:70px}
.layout{
  display:grid;
  grid-template-columns:245px minmax(0,1fr);
  gap:22px;
}
.sidebar{
  background:#fff;
  border:1px solid var(--line);
  border-radius:10px;
  height:max-content;
  overflow:hidden;
}
.side-title{
  padding:13px 15px;
  font-weight:800;
  background:#f7f9fb;
  border-bottom:1px solid var(--line);
}
.side-section{padding:12px 14px;border-bottom:1px solid var(--line)}
.side-section:last-child{border-bottom:0}
.side-section h3{
  margin:0 0 8px;
  font-size:1rem;
}
.side-link{
  display:flex;
  justify-content:space-between;
  align-items:center;
  padding:6px 8px;
  border-radius:6px;
  text-decoration:none;
  font-size:.92rem;
}
.side-link:hover,.side-link.active{background:#edf5ff;color:var(--blue)}
.count{color:#98a2b3;font-size:.82rem}

.content-head{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;
  gap:12px;
  flex-wrap:wrap;
  margin-bottom:10px;
}
.content-head h2{
  margin:0;
  font-size:1.65rem;
}
.muted{color:var(--muted);font-size:.9rem}
.toolbar{
  display:flex;
  gap:8px;
  align-items:center;
  flex-wrap:wrap;
  margin:10px 0 18px;
}
.toolbar form{display:flex;gap:8px}
.toolbar select,
.toolbar input{
  height:38px;
  border:1px solid #cfd7e3;
  background:#fff;
  padding:0 11px;
  border-radius:6px;
}
.toolbar select{min-width:170px}

.pills{
  display:flex;
  gap:7px;
  flex-wrap:wrap;
  margin:8px 0 18px;
}
.pill{
  padding:5px 11px;
  border:1px solid #cfd7e3;
  background:#fff;
  border-radius:999px;
  text-decoration:none;
  font-size:.85rem;
}
.pill.active{background:var(--blue);border-color:var(--blue);color:#fff}

.grid{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:16px;
}
.card{
  background:var(--card);
  border:1px solid var(--line);
  border-radius:9px;
  overflow:hidden;
  display:flex;
  flex-direction:column;
  min-width:0;
  transition:transform .16s, box-shadow .16s;
}
.card:hover{
  transform:translateY(-3px);
  box-shadow:0 12px 22px rgba(15,23,42,.10);
}
.card-img{
  position:relative;
  aspect-ratio:1/1;
  background:
    linear-gradient(45deg,#edf1f5 25%,transparent 25%),
    linear-gradient(-45deg,#edf1f5 25%,transparent 25%),
    linear-gradient(45deg,transparent 75%,#edf1f5 75%),
    linear-gradient(-45deg,transparent 75%,#edf1f5 75%);
  background-size:22px 22px;
  background-position:0 0,0 11px,11px -11px,-11px 0;
  display:grid;
  place-items:center;
  overflow:hidden;
}
.card-img img{
  width:100%;
  height:100%;
  object-fit:contain;
  background:#fff;
}
.placeholder{
  width:73%;
  height:73%;
  display:grid;
  place-items:center;
  text-align:center;
  border:2px solid #bfc9d6;
  background:linear-gradient(180deg,#fff,#e8edf3);
  color:#284565;
  font-weight:800;
  padding:12px;
  clip-path:polygon(50% 0,61% 9%,84% 10%,77% 28%,100% 41%,83% 54%,92% 83%,65% 75%,50% 100%,35% 75%,8% 83%,17% 54%,0 41%,23% 28%,16% 10%,39% 9%);
}
.badge{
  position:absolute;
  left:9px;
  top:9px;
  padding:3px 8px;
  border-radius:4px;
  background:var(--red);
  color:#fff;
  font-size:.72rem;
  font-weight:800;
  z-index:2;
}
.badge.green{background:var(--green)}
.badge.dark{background:var(--navy)}

.card-body{padding:12px 12px 13px;display:flex;flex-direction:column;gap:5px;flex:1}
.product-name{
  text-decoration:none;
  font-weight:700;
  font-size:.96rem;
  min-height:47px;
}
.product-name:hover{color:var(--blue)}
.meta{
  display:flex;
  gap:6px;
  flex-wrap:wrap;
}
.tag{
  display:inline-block;
  font-size:.72rem;
  background:#edf2f7;
  color:#4a5568;
  padding:2px 7px;
  border-radius:4px;
}
.price-row{
  display:flex;
  align-items:baseline;
  gap:8px;
  margin-top:auto;
}
.price{
  font-size:1.2rem;
  font-weight:800;
  color:var(--blue-2);
}
.old-price{
  color:#9aa4b2;
  text-decoration:line-through;
  font-size:.82rem;
}
.card-footer{padding-top:7px}
.card-footer form{margin:0}
.buy-btn{width:100%}

.breadcrumb{
  margin-top:12px;
}
.breadcrumb .wrap{
  font-size:.87rem;
  color:var(--muted);
}
.breadcrumb a{text-decoration:none}
.breadcrumb a:hover{color:var(--blue)}

.detail{
  background:#fff;
  border:1px solid var(--line);
  border-radius:10px;
  padding:20px;
}
.detail-grid{
  display:grid;
  grid-template-columns:minmax(280px,1fr) minmax(300px,1fr);
  gap:28px;
}
.detail-image{
  aspect-ratio:1/1;
  background:#f7f9fb;
  border-radius:8px;
  overflow:hidden;
}
.detail-image img{width:100%;height:100%;object-fit:contain}
.detail-info h1{margin:0 0 7px;font-size:2rem;line-height:1.2}
.detail-info p{color:#596575}
.detail-price{font-size:1.7rem;font-weight:800;color:var(--blue-2)}
.detail-old{text-decoration:line-through;color:#9aa4b2;margin-left:7px}
.stock-ok{color:var(--green);font-weight:600}
.stock-out{color:var(--red);font-weight:600}
.qty{
  width:90px;
  height:40px;
  border:1px solid #cfd7e3;
  border-radius:6px;
  padding:0 10px;
}
.form-row{display:flex;gap:8px;align-items:center;margin-top:12px}

.flash{
  max-width:var(--max);
  margin:14px auto 0;
  padding:10px 20px;
}
.flash div{
  background:#fff4cf;
  border:1px solid #f0d675;
  color:#6b5600;
  padding:9px 12px;
  border-radius:7px;
}

.table-wrap{
  overflow:auto;
  background:#fff;
  border:1px solid var(--line);
  border-radius:9px;
}
table{width:100%;border-collapse:collapse;min-width:650px}
th,td{padding:11px 12px;border-bottom:1px solid var(--line);text-align:left}
th{background:#f7f9fb;font-weight:700}
.total{
  text-align:right;
  font-size:1.4rem;
  font-weight:800;
  margin:18px 0;
}

.form-card{
  max-width:600px;
  background:#fff;
  border:1px solid var(--line);
  border-radius:9px;
  padding:22px;
}
label{display:block;font-weight:600;margin:12px 0 5px}
.form-card input{
  width:100%;
  height:42px;
  border:1px solid #cfd7e3;
  border-radius:6px;
  padding:0 11px;
}
.form-card input:focus{outline:2px solid rgba(37,99,235,.16);border-color:var(--blue)}

.footer{
  background:#111827;
  color:#d7dfeb;
  margin-top:20px;
}
.footer .wrap{padding-top:30px;padding-bottom:30px}
.footer h3{margin-top:0;color:#fff}
.footer-grid{
  display:grid;
  grid-template-columns:1.3fr 1fr 1fr 1.4fr;
  gap:20px;
}
.footer p strong{color:#fff}
.footer h3 a{color:#fff}
.footer h3 a:hover{color:#8edcff}
.st{display:inline-block;padding:4px 12px;border-radius:999px;font-weight:700;font-size:13px;line-height:1.35}
.st-pending{background:#fff4db;color:#9a6700}
.st-reported{background:#e0efff;color:#1d4ed8}
.st-paid{background:#ffedd5;color:#b45309}
.st-preparing{background:#ede9fe;color:#6d28d9}
.st-shipping{background:#cffafe;color:#0e7490}
.st-delivered{background:#dcfce7;color:#15803d}
.st-cancelled{background:#fee2e2;color:#b91c1c}
@media (max-width:1000px){.footer-grid{grid-template-columns:1fr 1fr}}
.footer p{color:#aeb8c6;margin:6px 0}
.footer a{text-decoration:none;color:#d7dfeb}
.footer a:hover{color:#fff}

.empty{
  padding:45px 15px;
  background:#fff;
  border:1px dashed #cbd5e1;
  border-radius:9px;
  text-align:center;
  color:var(--muted);
}

@media (max-width:1100px){
  .grid{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media (max-width:860px){
  .layout{grid-template-columns:1fr}
  .sidebar{display:none}
  .main-head .wrap{flex-wrap:wrap;padding-top:10px;padding-bottom:10px}
  .search{order:3;flex-basis:100%;max-width:none}
  .hero-box{min-height:195px;padding:24px}
  .detail-grid{grid-template-columns:1fr}
}
@media (max-width:650px){
  .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
  .hero h1{font-size:1.65rem}
  .hero-box{padding:20px}
  .logo{font-size:1.4rem}
  .head-actions a{padding:5px 7px}
  .product-name{font-size:.88rem}
  .price{font-size:1.05rem}
  .footer-grid{grid-template-columns:1fr}
}
@media (max-width:460px){
  .grid{grid-template-columns:1fr 1fr}
  .card-body{padding:9px}
  .meta .tag{font-size:.68rem}
}
</style>
</head>

<body>
<header class="main-head">
  <div class="wrap">
    <a class="logo" href="{{ url_for('home') }}"><img class="logo-img{{ ' round' if logo_default else '' }}" src="{{ logo_url }}" alt="PJGUNPLA"><div class="logo-text">PJ<span>GUNPLA</span><small>GUNDAM PLASTIC MODEL</small></div></a>

    <form class="search" method="get" action="{{ url_for('home') }}">
      <input
        type="search"
        name="q"
        value="{{ q or '' }}"
        placeholder="ค้นหาสินค้า เช่น Gundam, Barbatos, MG..."
        aria-label="ค้นหาสินค้า"
      >
      {% if grade %}
      <input type="hidden" name="grade" value="{{ grade }}">
      {% endif %}
      <button type="submit">🔍</button>
    </form>

    <div class="head-actions">
      {% if user_role != 'admin' %}<a href="{{ url_for('cart') }}">🛒 ตะกร้า ({{ cart_count }})</a>{% endif %}
      {% if user %}{% if user_role != 'admin' %}<a href="{{ url_for('my_orders') }}">📦 คำสั่งซื้อ</a>{% endif %}<a href="{{ url_for('profile') }}">👤 ข้อมูลส่วนตัว</a>{% endif %}
      {% if user_role == 'admin' %}
        <a href="{{ url_for('admin_dashboard') }}">⚙️ แอดมิน</a>
      {% endif %}
      {% if user %}
        <a href="{{ url_for('logout') }}">ออกจากระบบ</a>
      {% else %}
        <a href="{{ url_for('login') }}">เข้าสู่ระบบ</a>
      {% endif %}
    </div>
  </div>
</header>

<nav class="category-nav">
  <div class="wrap">
    <a class="{{ 'active' if not grade else '' }}" href="{{ url_for('home') }}">GUNDAM GUNPLA</a>
    {% for g in grades %}
      <a class="{{ 'active' if grade == g else '' }}" href="{{ url_for('home', grade=g, q=q) }}">{{ g }}</a>
    {% endfor %}
    <a href="{{ url_for('home', sale='1', q=q) }}">🔥 SALE</a>
    <a href="{{ url_for('home', new='1', q=q) }}">✨ NEW ARRIVAL</a>
  </div>
</nav>

{% for m in get_flashed_messages() %}
<div class="flash"><div>{{ m }}</div></div>
{% endfor %}

{% block full_content %}{% endblock %}

<footer class="footer">
  <div class="wrap">
    <div class="footer-grid">
      <div>
        <h3>PJ GUNPLA</h3>
        <p>ร้านจำลองสำหรับโปรเจกต์ Flask</p>
        <p>Gundam Plastic Model • FUN TO BUILD GUNPLA</p>
      </div>
      <div>
        <h3>หมวดสินค้า</h3>
        <p><a href="{{ url_for('home') }}">Gundam Gunpla</a></p>
        <p><a href="{{ url_for('home', grade='HG') }}">High Grade (HG)</a></p>
        <p><a href="{{ url_for('home', grade='RG') }}">Real Grade (RG)</a></p>
        <p><a href="{{ url_for('home', grade='MG') }}">Master Grade (MG)</a></p>
      </div>
      <div>
        <h3>บัญชีของฉัน</h3>
        <p><a href="{{ url_for('cart') }}">ตะกร้าสินค้า</a></p>
        <p><a href="{{ url_for('login') }}">เข้าสู่ระบบ</a></p>
        <p><a href="{{ url_for('register') }}">สมัครสมาชิก</a></p>
      </div>
      <div>
        <h3><a href="{{ url_for('owner_page') }}">ข้อมูลเจ้าของร้าน ›</a></h3>
        <p><strong><a href="{{ url_for('owner_page') }}">{{ owner.full_name }}</a></strong><br>{{ owner.position }}</p>
        <p>📞 <a href="tel:{{ owner.phone }}">{{ owner.phone }}</a></p>
        <p>Facebook: {{ owner.facebook }}</p>
        {% if shop_contact.email %}<p>✉️ <a href="mailto:{{ shop_contact.email }}">{{ shop_contact.email }}</a></p>{% endif %}
        {% if shop_contact.line %}<p>LINE: {{ shop_contact.line }}</p>{% endif %}
        {% if shop_contact.address %}<p>📍 {{ shop_contact.address }}</p>{% endif %}
        <p><a href="{{ url_for('owner_page') }}" style="color:#8edcff">ดูข้อมูลเจ้าของร้านทั้งหมด →</a></p>
      </div>
    </div>
  </div>
</footer>
</body>
</html>
"""

HOME = r"""{% extends 'base.html' %}
{% block title %}PJ GUNPLA | Gundam Plastic Model{% endblock %}

{% block full_content %}
<section class="hero">
  <div class="hero-box">
    <div class="hero-content">
      <div class="hero-kicker">GUNDAM PLASTIC MODEL</div>
      <h1>FUN TO BUILD GUNPLA</h1>
      <p>รวม Gunpla หลายเกรดในหน้าร้านเดียว ค้นหาและเลือกซื้อได้ง่าย พร้อมระบบตะกร้าสินค้า</p>
      <div class="hero-buttons">
        <a class="btn btn-primary" href="#products">ดูสินค้าทั้งหมด</a>
        <a class="btn btn-dark" href="{{ url_for('home', sale='1') }}">ดูสินค้า SALE</a>
      </div>
    </div>
    <img class="hero-logo{{ ' round' if logo_default else '' }}" src="{{ logo_url }}" alt="โลโก้ PJGUNPLA">
  </div>
</section>

<section class="page">
  <div class="wrap">
    <div class="layout">
      <aside class="sidebar">
        <div class="side-title">OUR PRODUCTS</div>

        <div class="side-section">
          <h3>หมวดหลัก</h3>
          <a class="side-link {{ 'active' if not grade and not sale and not new else '' }}" href="{{ url_for('home') }}">
            <span>🔵 GUNDAM GUNPLA</span>
            <span class="count">{{ all_count }}</span>
          </a>
          <a class="side-link {{ 'active' if sale else '' }}" href="{{ url_for('home', sale='1', q=q) }}">
            <span>🔥 CLEARANCE SALE</span>
            <span class="count">{{ sale_count }}</span>
          </a>
          <a class="side-link {{ 'active' if new else '' }}" href="{{ url_for('home', new='1', q=q) }}">
            <span>✨ NEW ARRIVAL</span>
            <span class="count">{{ new_count }}</span>
          </a>
        </div>

        <div class="side-section">
          <h3>GRADE</h3>
          {% for g in grades %}
          <a class="side-link {{ 'active' if grade == g else '' }}" href="{{ url_for('home', grade=g, q=q) }}">
            <span>{{ g }} — {{ grade_names[g] }}</span>
            <span class="count">{{ grade_counts[g] }}</span>
          </a>
          {% endfor %}
        </div>
      </aside>

      <main id="products">
        <div class="content-head">
          <div>
            <h2>🔵 GUNDAM GUNPLA</h2>
            <div class="muted">สินค้าทั้งหมด {{ shown_count }} รายการ</div>
          </div>
        </div>

        <div class="pills">
          <a class="pill {{ 'active' if not grade else '' }}" href="{{ url_for('home', q=q, sale=('1' if sale else None), new=('1' if new else None)) }}">ทั้งหมด</a>
          {% for g in grades %}
            <a class="pill {{ 'active' if grade == g else '' }}" href="{{ url_for('home', grade=g, q=q, sale=('1' if sale else None), new=('1' if new else None)) }}">{{ g }}</a>
          {% endfor %}
        </div>

        <div class="toolbar">
          <form method="get" action="{{ url_for('home') }}">
            {% if grade %}<input type="hidden" name="grade" value="{{ grade }}">{% endif %}
            {% if sale %}<input type="hidden" name="sale" value="1">{% endif %}
            {% if new %}<input type="hidden" name="new" value="1">{% endif %}
            <select name="sort" onchange="this.form.submit()">
              <option value="default" {% if sort == 'default' %}selected{% endif %}>เรียงตามสินค้าแนะนำ</option>
              <option value="price_asc" {% if sort == 'price_asc' %}selected{% endif %}>ราคา: ต่ำ → สูง</option>
              <option value="price_desc" {% if sort == 'price_desc' %}selected{% endif %}>ราคา: สูง → ต่ำ</option>
              <option value="name" {% if sort == 'name' %}selected{% endif %}>ชื่อสินค้า A → Z</option>
            </select>
          </form>

          {% if q %}
            <span class="muted">ผลการค้นหา: “{{ q }}”</span>
          {% endif %}
          {% if grade %}
            <span class="muted">/ เกรด {{ grade }}</span>
          {% endif %}
        </div>

        {% if products %}
        <div class="grid">
          {% for p in products %}
          <article class="card">
            <div class="card-img">
              {% set u = img_of(p) %}
              {% if p.badge == "SALE" %}
                <span class="badge">SALE</span>
              {% elif p.badge == "NEW" %}
                <span class="badge green">NEW</span>
              {% elif p.badge == "HOT" %}
                <span class="badge dark">HOT</span>
              {% elif p.badge == "SOLD OUT" %}
                <span class="badge dark">SOLD OUT</span>
              {% endif %}

              {% if u %}
                <img src="{{ u }}" alt="{{ p.name }}" loading="lazy">
              {% else %}
                <div class="placeholder">{{ p.grade }}<br>{{ p.name }}</div>
              {% endif %}
            </div>

            <div class="card-body">
              <div class="meta">
                <span class="tag">{{ p.grade }}</span>
                <span class="tag">{{ p.scale }}</span>
              </div>
              <a class="product-name" href="{{ url_for('product', pid=p.id) }}">{{ p.name }}</a>

              <div class="price-row">
                <span class="price">฿{{ '{:,}'.format(p.price) }}</span>
                {% if p.old_price %}
                  <span class="old-price">฿{{ '{:,}'.format(p.old_price) }}</span>
                {% endif %}
              </div>

              <div class="card-footer">
                {% if p.stock %}
                  <form method="post" action="{{ url_for('add', pid=p.id) }}">
                    <input type="hidden" name="qty" value="1">
                    <button class="btn btn-primary buy-btn" type="submit">สั่งซื้อ</button>
                  </form>
                {% else %}
                  <button class="btn btn-muted buy-btn" disabled>สินค้าหมด</button>
                {% endif %}
              </div>
            </div>
          </article>
          {% endfor %}
        </div>
        {% else %}
          <div class="empty">
            <div style="font-size:2rem">🔎</div>
            ไม่พบสินค้าที่ตรงกับเงื่อนไขที่เลือก
            <br>
            <a href="{{ url_for('home') }}">แสดงสินค้าทั้งหมด</a>
          </div>
        {% endif %}
      </main>
    </div>
  </div>
</section>
{% endblock %}
"""

PRODUCT = r"""{% extends 'base.html' %}
{% block title %}{{ p.name }} | PJ GUNPLA{% endblock %}

{% block full_content %}
<div class="breadcrumb"><div class="wrap">
  <a href="{{ url_for('home') }}">GUNDAM GUNPLA</a> / {{ p.name }}
</div></div>

<section class="page">
  <div class="wrap">
    <div class="detail">
      <div class="detail-grid">
        <div class="detail-image">
          {% set u = img_of(p) %}
          {% if u %}
            <img src="{{ u }}" alt="{{ p.name }}">
          {% else %}
            <div class="placeholder" style="width:65%;height:65%;margin:17.5%;font-size:1.15rem">
              {{ p.grade }}<br>{{ p.name }}
            </div>
          {% endif %}
        </div>

        <div class="detail-info">
          <div class="meta">
            <span class="tag">{{ p.grade }}</span>
            <span class="tag">{{ p.scale }}</span>
            <span class="tag">{{ p.category }}</span>
          </div>

          <h1>{{ p.name }}</h1>

          <div style="margin:18px 0 4px">
            <span class="detail-price">฿{{ '{:,}'.format(p.price) }}</span>
            {% if p.old_price %}
              <span class="detail-old">฿{{ '{:,}'.format(p.old_price) }}</span>
            {% endif %}
          </div>

          {% if p.stock %}
            <div class="stock-ok">✓ มีสินค้าในสต็อก {{ p.stock }} ชิ้น</div>
          {% else %}
            <div class="stock-out">✕ สินค้าหมดชั่วคราว</div>
          {% endif %}

          <p>{{ p.desc }}</p>

          {% if p.stock %}
          <form method="post" action="{{ url_for('add', pid=p.id) }}">
            <div class="form-row">
              <input class="qty" type="number" name="qty" min="1" max="{{ p.stock }}" value="1">
              <button class="btn btn-primary" type="submit">🛒 เพิ่มลงตะกร้า</button>
            </div>
          </form>
          {% else %}
            <button class="btn btn-muted" disabled>สินค้าหมด</button>
          {% endif %}

          <p style="margin-top:18px">
            <a href="{{ url_for('home') }}">← กลับไปเลือกสินค้า</a>
          </p>
        </div>
      </div>
    </div>
  </div>
</section>
{% endblock %}
"""

CART = r"""{% extends 'base.html' %}
{% block title %}ตะกร้าสินค้า | PJ GUNPLA{% endblock %}

{% block full_content %}
<div class="breadcrumb"><div class="wrap">ตะกร้าสินค้า</div></div>
<section class="page">
  <div class="wrap">
    <h2>🛒 ตะกร้าสินค้า</h2>

    {% if items %}
    <div class="table-wrap">
      <table>
        <tr>
          <th>สินค้า</th>
          <th>เกรด</th>
          <th>ราคา</th>
          <th>จำนวน</th>
          <th>รวม</th>
          <th></th>
        </tr>
        {% for i in items %}
        <tr>
          <td>
            <strong>{{ i.p.name }}</strong>
          </td>
          <td>{{ i.p.grade }}</td>
          <td>฿{{ '{:,}'.format(i.p.price) }}</td>
          <td>{{ i.qty }}</td>
          <td>฿{{ '{:,}'.format(i.sub) }}</td>
          <td>
            <form method="post" action="{{ url_for('remove', pid=i.p.id) }}">
              <button class="btn btn-danger" type="submit">ลบ</button>
            </form>
          </td>
        </tr>
        {% endfor %}
      </table>
    </div>

    <p class="total">รวมทั้งหมด ฿{{ '{:,}'.format(total) }}</p>
    <div style="display:flex;justify-content:flex-end;gap:8px">
      <a class="btn btn-dark" href="{{ url_for('home') }}">เลือกสินค้าเพิ่ม</a>
      <a class="btn btn-primary" href="{{ url_for('checkout') }}">ไปหน้าชำระเงิน</a>
    </div>
    {% else %}
      <div class="empty">
        🛒 ตะกร้ายังว่างอยู่
        <br>
        <a href="{{ url_for('home') }}">เลือก Gunpla ไปต่อได้เลย</a>
      </div>
    {% endif %}
  </div>
</section>
{% endblock %}
"""

CHECKOUT = r"""{% extends 'base.html' %}
{% block title %}ยืนยันที่อยู่จัดส่ง | PJ GUNPLA{% endblock %}
{% block full_content %}
<div class="breadcrumb"><div class="wrap">ยืนยันที่อยู่จัดส่ง</div></div>
<section class="page"><div class="wrap">
  <div class="form-card">
    <h2>📦 ตรวจสอบข้อมูลจัดส่ง</h2>
    <p class="muted">ยอดที่ต้องชำระ <strong style="color:#1d4ed8">฿{{ '{:,}'.format(total) }}</strong></p>
    <form method="post">
      <label for="name">ชื่อผู้รับ <small class="muted">(ชื่อ-นามสกุล)</small></label>
      <input id="name" name="name" maxlength="120" autocomplete="name" placeholder="เช่น สมชาย ใจดี"
             pattern="[A-Za-z\u0E01-\u0E3A\u0E40-\u0E4E][A-Za-z\u0E01-\u0E3A\u0E40-\u0E4E.'\-]+(?:\s+[A-Za-z\u0E01-\u0E3A\u0E40-\u0E4E][A-Za-z\u0E01-\u0E3A\u0E40-\u0E4E.'\-]+)+"
             title="ต้องเป็นชื่อและนามสกุล คั่นด้วยเว้นวรรค ตัวอักษรไทยหรืออังกฤษเท่านั้น เช่น สมชาย ใจดี"
             value="{{ form.get('name', '') }}" required>
      {% if errors.name %}<div class="field-error">{{ errors.name }}</div>{% endif %}

      {% if need_email %}
      <label for="email">อีเมล <small class="muted">(บันทึกเข้าบัญชีของคุณ)</small></label>
      <input id="email" name="email" type="email" maxlength="254" placeholder="name@example.com" value="{{ form.get('email', '') }}" required>
      {% if errors.email %}<div class="field-error">{{ errors.email }}</div>{% endif %}
      {% endif %}

      <label for="phone">เบอร์โทรศัพท์ <small class="muted">(ตัวเลขเท่านั้น 9-10 หลัก)</small></label>
      <input id="phone" name="phone" type="tel" inputmode="numeric" maxlength="10" placeholder="0812345678"
             pattern="0[0-9]{8,9}" title="ตัวเลขเท่านั้น ขึ้นต้นด้วย 0 และมี 9-10 หลัก เช่น 0812345678"
             oninput="this.value=this.value.replace(/[^0-9]/g,'')" value="{{ form.get('phone', '') }}" required>
      {% if errors.phone %}<div class="field-error">{{ errors.phone }}</div>{% endif %}

      <label for="addr">บ้านเลขที่ / หมู่บ้าน / ถนน</label>
      <input id="addr" name="addr" maxlength="250" placeholder="เช่น 123/4 หมู่ 5 ถ.มิตรภาพ"
             pattern=".*[0-9\u0E50-\u0E59].*" title="ต้องมีบ้านเลขที่ (ตัวเลข) เช่น 123/4 หมู่ 5 ถ.มิตรภาพ"
             value="{{ form.get('addr', '') }}" required>
      {% if errors.addr %}<div class="field-error">{{ errors.addr }}</div>{% endif %}

      <label for="subdistrict">ตำบล / แขวง</label>
      <input id="subdistrict" name="subdistrict" maxlength="100" placeholder="ภาษาไทยเท่านั้น เช่น ในเมือง"
             pattern="[\u0E01-\u0E3A\u0E40-\u0E4E\s.\-]{2,}" title="ตัวอักษรไทยเท่านั้น ไม่มีตัวเลข"
             value="{{ form.get('subdistrict', '') }}" required>
      {% if errors.subdistrict %}<div class="field-error">{{ errors.subdistrict }}</div>{% endif %}

      <label for="district">อำเภอ / เขต</label>
      <input id="district" name="district" maxlength="100" placeholder="ภาษาไทยเท่านั้น เช่น เมืองขอนแก่น"
             pattern="[\u0E01-\u0E3A\u0E40-\u0E4E\s.\-]{2,}" title="ตัวอักษรไทยเท่านั้น ไม่มีตัวเลข"
             value="{{ form.get('district', '') }}" required>
      {% if errors.district %}<div class="field-error">{{ errors.district }}</div>{% endif %}

      <label for="province">จังหวัด</label>
      <input id="province" name="province" maxlength="100" list="province-list" autocomplete="off"
             placeholder="พิมพ์แล้วเลือกจากรายการ" value="{{ form.get('province', '') }}" required>
      <datalist id="province-list">{% for pv in provinces %}<option value="{{ pv }}">{% endfor %}</datalist>
      {% if errors.province %}<div class="field-error">{{ errors.province }}</div>{% endif %}

      <label for="zipcode">รหัสไปรษณีย์</label>
      <input id="zipcode" name="zipcode" pattern="[0-9]{5}" maxlength="5" inputmode="numeric" placeholder="เช่น 40000"
             title="ตัวเลข 5 หลัก" oninput="this.value=this.value.replace(/[^0-9]/g,'')"
             value="{{ form.get('zipcode', '') }}" required>
      {% if errors.zipcode %}<div class="field-error">{{ errors.zipcode }}</div>{% endif %}
      <p class="muted">เมื่อกดปุ่มด้านล่าง ระบบจะบันทึกคำสั่งซื้อและแสดง QR สำหรับสแกนจ่ายเงิน โปรดตรวจสอบชื่อผู้รับและที่อยู่ให้ถูกต้อง</p>
      <div style="margin-top:18px"><button class="btn btn-primary" type="submit">ยืนยันที่อยู่และไปชำระเงิน</button>
      <a class="btn btn-dark" href="{{ url_for('cart') }}">กลับไปตะกร้า</a></div>
    </form>
  </div>
</div></section>
<style>.field-error{color:#b91c1c;font-size:13.5px;margin:4px 2px 0}</style>
<script>
(function(){
  var input=document.getElementById('province');
  var list=[].map.call(document.querySelectorAll('#province-list option'),function(o){return o.value});
  var alias={'กทม':'กรุงเทพมหานคร','กรุงเทพ':'กรุงเทพมหานคร','กรุงเทพฯ':'กรุงเทพมหานคร','อยุธยา':'พระนครศรีอยุธยา','โคราช':'นครราชสีมา'};
  function check(){
    var v=input.value.trim().replace(/^(จังหวัด|จ\.)\s*/,'');
    v=alias[v]||v;
    input.setCustomValidity(v&&list.indexOf(v)<0?'ไม่พบจังหวัดนี้ กรุณาพิมพ์ชื่อจังหวัดให้ถูกต้อง':'');
  }
  input.addEventListener('input',check); check();
})();
</script>
{% endblock %}
"""

