def brand_logo_default_bytes():
    import base64
    return base64.b64decode("".join(BRAND_LOGO_B64.split()))


def shop_logo_bytes():
    """ไบต์ของโลโก้ที่ใช้อยู่ (โลโก้ที่แอดมินอัปโหลด ถ้าไม่มีใช้โลโก้เริ่มต้น)"""
    custom = get_setting("shop_logo", "")
    if custom:
        try:
            with open(os.path.join(UPLOAD_DIR, os.path.basename(custom)), "rb") as fh:
                return fh.read()
        except OSError:
            pass
    return brand_logo_default_bytes()


@app.route("/brand/logo.jpg")
def brand_logo():
    response = app.response_class(brand_logo_default_bytes(), mimetype="image/jpeg")
    response.headers["Cache-Control"] = "public, max-age=86400"
    return response


@app.context_processor
def inject_globals():
    custom_logo = get_setting("shop_logo", "")
    return {
        "logo_url": url_for("static", filename="uploads/" + custom_logo) if custom_logo else url_for("brand_logo"),
        "logo_default": not custom_logo,
        "owner": OWNER_LOCKED,
        "shop_contact": {
            "email": get_setting("owner_email", ""),
            "line": get_setting("owner_line_oa", ""),
            "address": get_setting("shop_address", ""),
        },
        "cart_count": sum(int(v) for v in session.get("cart", {}).values()),
        "user": session.get("uname"),
        "user_role": session.get("role", "customer"),
        "img_of": img_of,
        "grades": GRADES,
        "grade_names": GRADE_NAMES,
    }


def login_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if "uid" not in session:
            flash("กรุณาเข้าสู่ระบบก่อนชำระเงิน")
            return redirect(url_for("login", next=request.path))
        return view(*args, **kwargs)
    return wrapped


def admin_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if "uid" not in session:
            flash("กรุณาเข้าสู่ระบบแอดมิน")
            return redirect(url_for("login", next=request.path))
        account = get_db().execute("SELECT role FROM users WHERE id=?", (session["uid"],)).fetchone()
        if not account or account["role"] != "admin":
            abort(403)
        session["role"] = "admin"
        return view(*args, **kwargs)
    return wrapped


def safe_next(target):
    if target and target.startswith("/") and not target.startswith("//"):
        return target
    return url_for("home")


def get_cart_items():
    items = []
    for pid_text, qty_value in session.get("cart", {}).items():
        try:
            pid, qty = int(pid_text), int(qty_value)
        except (TypeError, ValueError):
            continue
        p = get_product(pid)
        if p and qty > 0:
            items.append({"p": p, "qty": qty, "sub": p["price"] * qty})
    return items


def money(value):
    return "฿{:,.2f}".format(float(value))


def tlv(tag, value):
    value = str(value)
    return f"{tag}{len(value):02d}{value}"


def crc16_ccitt(payload):
    crc = 0xFFFF
    for char in payload.encode("ascii"):
        crc ^= char << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF
    return f"{crc:04X}"


# ------------------------------------------------------------------
# สร้าง QR code ด้วย Python ล้วน (ไม่ต้องติดตั้งไลบรารี qrcode) — โหมด byte, แก้ไขข้อผิดพลาดระดับ M, เวอร์ชัน 1-6
# ------------------------------------------------------------------
_QR_ECC_PER_BLOCK_M = {1: 10, 2: 16, 3: 26, 4: 18, 5: 24, 6: 16}
_QR_NUM_BLOCKS_M = {1: 1, 2: 1, 3: 1, 4: 2, 5: 2, 6: 4}


def _qr_raw_codewords(ver):
    result = (16 * ver + 128) * ver + 64
    if ver >= 2:
        num_align = ver // 7 + 2
        result -= (25 * num_align - 10) * num_align - 55
    return result // 8


def _qr_data_codewords(ver):
    return _qr_raw_codewords(ver) - _QR_ECC_PER_BLOCK_M[ver] * _QR_NUM_BLOCKS_M[ver]


def _gf_mul(x, y):
    z = 0
    for i in range(7, -1, -1):
        z = (z << 1) ^ ((z >> 7) * 0x11D)
        z ^= ((y >> i) & 1) * x
    return z


def _rs_divisor(degree):
    result = [0] * (degree - 1) + [1]
    root = 1
    for _ in range(degree):
        for j in range(degree):
            result[j] = _gf_mul(result[j], root)
            if j + 1 < degree:
                result[j] ^= result[j + 1]
        root = _gf_mul(root, 0x02)
    return result


def _rs_remainder(data, divisor):
    result = [0] * len(divisor)
    for byte in data:
        factor = byte ^ result.pop(0)
        result.append(0)
        for i, coef in enumerate(divisor):
            result[i] ^= _gf_mul(coef, factor)
    return result


def qr_modules(text):
    """สร้างเมทริกซ์ QR (list ของ list ค่า bool, True = จุดดำ) จากข้อความ"""
    data_bytes = text.encode("utf-8")
    ver = next((v for v in range(1, 7) if 4 + 8 + 8 * len(data_bytes) <= _qr_data_codewords(v) * 8), None)
    if ver is None:
        raise ValueError("ข้อความยาวเกินกว่าที่ QR ของระบบรองรับ")
    # --- bit stream: โหมด byte (0100) + จำนวนตัวอักษร 8 บิต + ข้อมูล
    bits = [0, 1, 0, 0] + [(len(data_bytes) >> i) & 1 for i in range(7, -1, -1)]
    for byte in data_bytes:
        bits += [(byte >> i) & 1 for i in range(7, -1, -1)]
    capacity = _qr_data_codewords(ver) * 8
    bits += [0] * min(4, capacity - len(bits))
    bits += [0] * (-len(bits) % 8)
    codewords = [int("".join(map(str, bits[i:i + 8])), 2) for i in range(0, len(bits), 8)]
    pad = 0xEC
    while len(codewords) < capacity // 8:
        codewords.append(pad)
        pad ^= 0xEC ^ 0x11
    # --- Reed-Solomon + สลับบล็อก
    num_blocks, ecc_len, raw = _QR_NUM_BLOCKS_M[ver], _QR_ECC_PER_BLOCK_M[ver], _qr_raw_codewords(ver)
    short_blocks = num_blocks - raw % num_blocks
    short_len = raw // num_blocks
    divisor = _rs_divisor(ecc_len)
    blocks, k = [], 0
    for i in range(num_blocks):
        chunk = codewords[k:k + short_len - ecc_len + (0 if i < short_blocks else 1)]
        k += len(chunk)
        ecc = _rs_remainder(chunk, divisor)
        if i < short_blocks:
            chunk = chunk + [0]
        blocks.append(chunk + ecc)
    final = []
    for i in range(len(blocks[0])):
        for j, block in enumerate(blocks):
            if i != short_len - ecc_len or j >= short_blocks:
                final.append(block[i])
    # --- วาด function patterns
    size = ver * 4 + 17
    modules = [[False] * size for _ in range(size)]
    is_func = [[False] * size for _ in range(size)]

    def set_func(x, y, dark):
        modules[y][x] = dark
        is_func[y][x] = True

    for i in range(size):
        set_func(6, i, i % 2 == 0)
        set_func(i, 6, i % 2 == 0)
    for cx, cy in ((3, 3), (size - 4, 3), (3, size - 4)):
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                x, y = cx + dx, cy + dy
                if 0 <= x < size and 0 <= y < size:
                    set_func(x, y, max(abs(dx), abs(dy)) not in (2, 4))
    if ver >= 2:
        num_align = ver // 7 + 2
        step = (ver * 4 + num_align * 2 + 1) // (num_align * 2 - 2) * 2
        pos = sorted([size - 7 - i * step for i in range(num_align - 1)] + [6])
        for i, ax in enumerate(pos):
            for j, ay in enumerate(pos):
                if (i == 0 and j == 0) or (i == 0 and j == len(pos) - 1) or (i == len(pos) - 1 and j == 0):
                    continue
                for dy in range(-2, 3):
                    for dx in range(-2, 3):
                        set_func(ax + dx, ay + dy, max(abs(dx), abs(dy)) != 1)

    def draw_format(mask):
        data = mask  # ระดับ M = 00
        rem = data
        for _ in range(10):
            rem = (rem << 1) ^ ((rem >> 9) * 0x537)
        fmt = ((data << 10) | rem) ^ 0x5412
        bit = lambda i: ((fmt >> i) & 1) != 0
        for i in range(6):
            set_func(8, i, bit(i))
        set_func(8, 7, bit(6))
        set_func(8, 8, bit(7))
        set_func(7, 8, bit(8))
        for i in range(9, 15):
            set_func(14 - i, 8, bit(i))
        for i in range(8):
            set_func(size - 1 - i, 8, bit(i))
        for i in range(8, 15):
            set_func(8, size - 15 + i, bit(i))
        set_func(8, size - 8, True)

    draw_format(0)
    # --- วางข้อมูลแบบซิกแซก
    i = 0
    for right in range(size - 1, 0, -2):
        if right == 6:
            right = 5
        for vert in range(size):
            for j in range(2):
                x = right - j
                y = size - 1 - vert if ((right + 1) & 2) == 0 else vert
                if not is_func[y][x] and i < len(final) * 8:
                    modules[y][x] = ((final[i >> 3] >> (7 - (i & 7))) & 1) != 0
                    i += 1

    def apply_mask(mask):
        for y in range(size):
            for x in range(size):
                if is_func[y][x]:
                    continue
                invert = (
                    (x + y) % 2 == 0, y % 2 == 0, x % 3 == 0, (x + y) % 3 == 0,
                    (x // 3 + y // 2) % 2 == 0, x * y % 2 + x * y % 3 == 0,
                    (x * y % 2 + x * y % 3) % 2 == 0, ((x + y) % 2 + x * y % 3) % 2 == 0,
                )[mask]
                if invert:
                    modules[y][x] = not modules[y][x]

    def penalty():
        score = 0
        lines = [row for row in modules] + [[modules[y][x] for y in range(size)] for x in range(size)]
        for line in lines:
            run = 1
            for a in range(1, size):
                if line[a] == line[a - 1]:
                    run += 1
                else:
                    if run >= 5:
                        score += 3 + run - 5
                    run = 1
            if run >= 5:
                score += 3 + run - 5
            text_line = "".join("1" if v else "0" for v in line)
            score += 40 * (text_line.count("10111010000") + text_line.count("00001011101"))
        for y in range(size - 1):
            for x in range(size - 1):
                if modules[y][x] == modules[y][x + 1] == modules[y + 1][x] == modules[y + 1][x + 1]:
                    score += 3
        dark = sum(v for row in modules for v in row)
        total = size * size
        score += ((abs(dark * 20 - total * 10) + total - 1) // total - 1) * 10
        return score

    best_mask, best_score = 0, None
    for mask in range(8):
        apply_mask(mask)
        draw_format(mask)
        score = penalty()
        if best_score is None or score < best_score:
            best_mask, best_score = mask, score
        apply_mask(mask)  # ย้อนกลับ (XOR ซ้ำ)
    apply_mask(best_mask)
    draw_format(best_mask)
    return modules


def qr_svg_data_uri(text, border=4):
    """คืน data URI ของรูป QR แบบ SVG (คมชัดทุกขนาด สแกนได้)"""
    modules = qr_modules(text)
    size = len(modules)
    parts = []
    for y, row in enumerate(modules):
        x = 0
        while x < size:
            if row[x]:
                start = x
                while x < size and row[x]:
                    x += 1
                parts.append(f"M{start + border},{y + border}h{x - start}v1h-{x - start}z")
            else:
                x += 1
    dim = size + border * 2
    svg = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {dim} {dim}" shape-rendering="crispEdges">'
           f'<rect width="{dim}" height="{dim}" fill="#fff"/><path d="{"".join(parts)}" fill="#000"/></svg>')
    return "data:image/svg+xml;base64," + base64.b64encode(svg.encode("utf-8")).decode("ascii")


# บัญชีรับเงินของร้าน (สร้าง QR PromptPay ตามยอดของแต่ละคำสั่งซื้อ)
SHOP_PAYMENT = {"promptpay_id": "0803251417", "bank": "ธนาคารกสิกรไทย", "bank_short": "KBANK"}


def promptpay_payload(promptpay_id, amount):
    """สร้างข้อความ PromptPay (EMV QR) แบบระบุยอดเงิน รองรับเบอร์มือถือและเลขบัตรประชาชน"""
    from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
    digits = re.sub(r"\D", "", promptpay_id or "")
    if len(digits) == 10 and digits.startswith("0"):
        account_tag, account_value = "01", "0066" + digits[1:]
    elif len(digits) == 13:
        account_tag, account_value = "02", digits
    else:
        raise ValueError("PromptPay ID ต้องเป็นเบอร์มือถือ 10 หลักหรือเลขบัตรประชาชน 13 หลัก")
    try:
        value = Decimal(str(amount)).quantize(Decimal("0.01"), ROUND_HALF_UP)
    except InvalidOperation:
        raise ValueError("ยอดเงินไม่ถูกต้อง")
    if value <= 0 or value >= Decimal("10000000000"):
        raise ValueError("ยอดเงินต้องมากกว่า 0")
    merchant_account = tlv("00", "A000000677010111") + tlv(account_tag, account_value)
    payload = (
        tlv("00", "01") + tlv("01", "12") + tlv("29", merchant_account)
        + tlv("58", "TH") + tlv("53", "764") + tlv("54", f"{value:.2f}")
    )
    to_crc = payload + "6304"
    return to_crc + crc16_ccitt(to_crc)


def make_qr_data_uri(promptpay_id, amount):
    """QR PromptPay ตามยอดเงิน (SVG data URI) — ไม่ต้องใช้ไลบรารีเพิ่ม"""
    if not promptpay_id:
        return None
    try:
        return qr_svg_data_uri(promptpay_payload(promptpay_id, amount))
    except ValueError:
        return None


def allowed_image(filename):
    return "." in filename and filename.rsplit(".", 1)[1].lower() in ALLOWED_IMAGE_EXTS


def save_uploaded_image(file_storage):
    if not file_storage or not file_storage.filename:
        return ""
    if not allowed_image(file_storage.filename):
        raise ValueError("ไฟล์รูปต้องเป็น JPG, JPEG, PNG หรือ WEBP")
    original = secure_filename(file_storage.filename)
    ext = original.rsplit(".", 1)[1].lower()
    unique_name = f"{uuid.uuid4().hex}.{ext}"
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    file_storage.save(os.path.join(UPLOAD_DIR, unique_name))
    return unique_name


def save_payment_slip(file_storage):
    """บันทึกสลิปโอนเงิน (JPG/PNG/WEBP) ลงโฟลเดอร์ slips/ คืนค่าชื่อไฟล์ที่บันทึก"""
    if not file_storage or not file_storage.filename:
        raise ValueError("กรุณาแนบรูปสลิปโอนเงิน")
    if not allowed_image(file_storage.filename):
        raise ValueError("สลิปต้องเป็นไฟล์รูป JPG, PNG หรือ WEBP")
    head = file_storage.stream.read(12)
    file_storage.stream.seek(0)
    if head.startswith(b"\xff\xd8\xff"):
        ext = "jpg"
    elif head.startswith(b"\x89PNG"):
        ext = "png"
    elif head[:4] == b"RIFF" and head[8:12] == b"WEBP":
        ext = "webp"
    else:
        raise ValueError("ไฟล์ที่แนบไม่ใช่รูปภาพที่ถูกต้อง")
    os.makedirs(SLIP_DIR, exist_ok=True)
    name = f"{uuid.uuid4().hex}.{ext}"
    file_storage.save(os.path.join(SLIP_DIR, name))
    return name


def remove_payment_slip(filename):
    if filename and re.fullmatch(r"[0-9a-f]{32}\.(jpg|png|webp)", filename):
        try:
            os.remove(os.path.join(SLIP_DIR, filename))
        except OSError:
            pass


def remove_uploaded_image(filename):
    if filename:
        path = os.path.join(UPLOAD_DIR, os.path.basename(filename))
        try:
            os.remove(path)
        except OSError:
            pass


