@app.route("/")
def home():
    grade = request.args.get("grade", "").upper().strip()
    q = request.args.get("q", "").strip()
    sort = request.args.get("sort", "default")
    sale = request.args.get("sale") == "1"
    new = request.args.get("new") == "1"
    products = [row_dict(r) for r in get_db().execute("SELECT * FROM products")]
    if grade:
        products = [p for p in products if p["grade"] == grade]
    if sale:
        products = [p for p in products if p["old_price"] is not None]
    if new:
        products = [p for p in products if p["badge"] == "NEW"]
    if q:
        query = q.casefold()
        products = [p for p in products if query in p["name"].casefold() or query in p["grade"].casefold()
                    or query in p["scale"].casefold() or query in p["category"].casefold()]
    if sort == "price_asc":
        products.sort(key=lambda p: p["price"])
    elif sort == "price_desc":
        products.sort(key=lambda p: p["price"], reverse=True)
    elif sort == "name":
        products.sort(key=lambda p: p["name"].lower())
    grade_counts = {item: sum(1 for p in get_db().execute("SELECT grade FROM products") if p["grade"] == item) for item in GRADES}
    all_products = [row_dict(r) for r in get_db().execute("SELECT * FROM products")]
    sale_count = sum(1 for p in all_products if p["old_price"] is not None)
    new_count = sum(1 for p in all_products if p["badge"] == "NEW")
    return render_template("home.html", products=products, grade=grade, q=q, sort=sort,
        sale=sale, new=new, shown_count=len(products), all_count=len(all_products),
        sale_count=sale_count, new_count=new_count, grade_counts=grade_counts)


