@app.post("/add/<int:pid>")
def add(pid):
    p = get_product(pid) or abort(404)
    qty = request.form.get("qty", 1, type=int)
    qty = max(1, qty or 1)
    cart = dict(session.get("cart", {}))
    current = int(cart.get(str(pid), 0))
    if p["stock"] <= 0:
        flash("สินค้าหมดแล้ว")
    elif current + qty > p["stock"]:
        flash(f"มีสินค้าในสต็อกเพียง {p['stock']} ชิ้น")
    else:
        cart[str(pid)] = current + qty
        session["cart"] = cart
        flash(f"เพิ่ม {p['name']} ลงตะกร้าแล้ว")
    return redirect(request.referrer or url_for("home"))


@app.post("/remove/<int:pid>")
def remove(pid):
    cart = dict(session.get("cart", {}))
    cart.pop(str(pid), None)
    session["cart"] = cart
    return redirect(url_for("cart"))


