THAI = "\u0E01-\u0E3A\u0E40-\u0E4E"          # พยัญชนะ สระ วรรณยุกต์ (ไม่รวมเลขไทย)
PHONE_RE = re.compile(r"0[0-9]{8,9}")          # 9-10 หลัก ขึ้นต้นด้วย 0 เฉพาะตัวเลข
ADDR_RE = re.compile(rf"[0-9\u0E50-\u0E59A-Za-z{THAI}\s/.,\-()#]+")
PLACE_RE = re.compile(rf"[{THAI}\s.\-]+")      # ตำบล/อำเภอ: ภาษาไทยล้วน ไม่มีตัวเลข
ZIP_RE = re.compile(r"[0-9]{5}")


def _clean(value):
    return re.sub(r"\s+", " ", (value or "").strip())


EMAIL_RE = re.compile(r"[A-Za-z0-9._%+\-]+@[A-Za-z0-9\-]+(?:\.[A-Za-z0-9\-]+)*\.[A-Za-z]{2,}")


NAME_TITLES = {"นาย", "นาง", "นางสาว", "น.ส.", "นส.", "ด.ช.", "ด.ญ.", "เด็กชาย", "เด็กหญิง", "คุณ",
               "mr", "mr.", "mrs", "mrs.", "ms", "ms.", "miss", "dr", "dr."}
NAME_ERROR = "ชื่อผู้รับต้องเป็นชื่อและนามสกุลจริง คั่นด้วยเว้นวรรค เช่น สมชาย ใจดี (ตัวอักษรไทยหรืออังกฤษเท่านั้น ไม่มีตัวเลข)"


def validate_full_name(value):
    """ตรวจชื่อ-นามสกุล: ต้องมีอย่างน้อย 2 คำ (ชื่อ + นามสกุล) เป็นตัวอักษรไทย/อังกฤษเท่านั้น
    คำนำหน้า (นาย นาง นางสาว ฯลฯ) ใส่ได้ แต่ไม่นับเป็นชื่อ  คืนค่า (ชื่อที่จัดช่องว่างแล้ว, ข้อความผิดพลาดหรือ None)"""
    name = " ".join((value or "").split())
    if not name:
        return "", "กรุณากรอกชื่อผู้รับ (ชื่อ-นามสกุล)"
    if len(name) > 120:
        return name, "ชื่อยาวเกินไป (ไม่เกิน 120 ตัวอักษร)"
    parts = name.split(" ")
    token_re = re.compile(rf"[A-Za-z{THAI}][A-Za-z{THAI}.'\-]*")
    if not all(token_re.fullmatch(t) for t in parts):
        return name, NAME_ERROR
    core = parts[1:] if parts[0].lower() in NAME_TITLES else parts
    if len(core) < 2 or len(core) > 6:
        return name, NAME_ERROR
    for token in core:
        letters = re.sub(r"[.'\-]", "", token)
        if len(letters) < 2 or len(set(letters.lower())) < 2:
            return name, NAME_ERROR
    return name, None


def validate_email(value):
    """คืนค่า (อีเมลตัวพิมพ์เล็ก, ข้อความผิดพลาดหรือ None)"""
    email = (value or "").strip().lower()
    if not email:
        return "", "กรุณากรอกอีเมล"
    if len(email) > 254 or ".." in email or not EMAIL_RE.fullmatch(email):
        return email, "รูปแบบอีเมลไม่ถูกต้อง เช่น name@example.com"
    return email, None


def validate_profile(form, is_admin, user_id):
    """ตรวจข้อมูลส่วนตัว: อีเมลบังคับ (ยกเว้นแอดมิน) ส่วนชื่อ/เบอร์/ที่อยู่ไม่บังคับ แต่ถ้ากรอกต้องถูกต้อง
    ที่อยู่ต้องกรอกครบทุกช่องหรือเว้นว่างทั้งหมด"""
    errors = {}
    addr_keys = ("addr", "subdistrict", "district", "province", "zipcode")
    has_addr = any((form.get(k) or "").strip() for k in addr_keys)
    has_phone = bool((form.get("phone") or "").strip())
    probe = {"name": "x", "phone": form.get("phone") if has_phone else "0000000000"}
    for k in addr_keys:
        probe[k] = form.get(k, "")
    if not has_addr:   # ไม่ได้กรอกที่อยู่เลย -> ใช้ค่าสมมติที่ผ่านเกณฑ์ เพื่อไม่ให้ฟ้อง error
        probe.update(addr="1", subdistrict="กข", district="กข", province="ขอนแก่น", zipcode="40000")
    clean, probe_errors = validate_shipping(probe)
    if has_phone and "phone" in probe_errors:
        errors["phone"] = probe_errors["phone"]
    if has_addr:
        errors.update({k: v for k, v in probe_errors.items() if k in addr_keys})
    out = {"phone": clean["phone"] if has_phone else ""}
    for k in addr_keys:
        out[k] = clean[k] if has_addr else ""
    full_name = _clean(form.get("full_name"))
    if full_name:
        full_name, name_error = validate_full_name(full_name)
        if name_error:
            errors["full_name"] = name_error
    out["full_name"] = full_name
    email_raw = (form.get("email") or "").strip()
    if is_admin and not email_raw:
        out["email"] = ""          # แอดมินไม่ต้องมีอีเมล
    else:
        out["email"], email_error = validate_email(email_raw)
        if email_error:
            errors["email"] = email_error
        elif email_in_use(out["email"], user_id):
            errors["email"] = "อีเมลนี้ถูกใช้โดยบัญชีอื่นแล้ว"
    return out, errors


def email_in_use(email, exclude_user_id=None):
    row = get_db().execute("SELECT id FROM users WHERE email=? AND id<>?", (email, exclude_user_id or 0)).fetchone()
    return row is not None


def _strip_prefix(value, prefixes):
    for prefix in prefixes:
        if value.startswith(prefix) and len(value) - len(prefix) >= 2:
            return value[len(prefix):].strip(" .")
    return value


def _valid_place(value):
    letters = re.sub(r"[\s.\-]", "", value)
    return bool(PLACE_RE.fullmatch(value)) and len(letters) >= 2 and len(set(letters)) >= 2


def normalize_province(value):
    value = _strip_prefix(_clean(value), ("จังหวัด", "จ."))
    return PROVINCE_ALIASES.get(value, value)


def validate_shipping(form):
    """คืนค่า (ข้อมูลที่ทำความสะอาดแล้ว, errors) — errors เป็น dict ชื่อช่อง -> ข้อความ ถ้าว่างแปลว่าผ่านทั้งหมด"""
    clean, errors = {}, {}

    name, name_error = validate_full_name(form.get("name"))
    if name_error:
        errors["name"] = name_error
    clean["name"] = name

    phone = (form.get("phone") or "").strip()
    if not phone:
        errors["phone"] = "กรุณากรอกเบอร์โทรศัพท์"
    elif not phone.isascii() or not phone.isdigit():
        errors["phone"] = "เบอร์โทรศัพท์ใส่ได้เฉพาะตัวเลข (ไม่ต้องมีขีดหรือเว้นวรรค)"
    elif not PHONE_RE.fullmatch(phone):
        errors["phone"] = "เบอร์โทรต้องขึ้นต้นด้วย 0 และมี 9-10 หลัก เช่น 0812345678"
    clean["phone"] = phone

    addr = _clean(form.get("addr"))
    if not addr:
        errors["addr"] = "กรุณากรอกบ้านเลขที่ / หมู่บ้าน / ถนน"
    elif not ADDR_RE.fullmatch(addr) or len(addr) < 2:
        errors["addr"] = "ที่อยู่มีอักขระที่ไม่ถูกต้อง ใช้ได้เฉพาะตัวอักษร ตัวเลข และ / . , - ( ) #"
    elif not re.search(r"[0-9\u0E50-\u0E59]", addr):
        errors["addr"] = "ต้องมีบ้านเลขที่ (ตัวเลข) เช่น 123/4 หมู่ 5 ถ.มิตรภาพ"
    clean["addr"] = addr

    subdistrict = _strip_prefix(_clean(form.get("subdistrict")), ("ตำบล", "แขวง", "ต.", "แขวง."))
    if not subdistrict:
        errors["subdistrict"] = "กรุณากรอกตำบล / แขวง"
    elif not _valid_place(subdistrict):
        errors["subdistrict"] = "ตำบล / แขวง ต้องเป็นตัวอักษรไทยที่ถูกต้อง และไม่มีตัวเลข"
    clean["subdistrict"] = subdistrict

    district = _strip_prefix(_clean(form.get("district")), ("อำเภอ", "เขต", "อ."))
    if not district:
        errors["district"] = "กรุณากรอกอำเภอ / เขต"
    elif not _valid_place(district):
        errors["district"] = "อำเภอ / เขต ต้องเป็นตัวอักษรไทยที่ถูกต้อง และไม่มีตัวเลข"
    clean["district"] = district

    province = normalize_province(form.get("province"))
    if not province:
        errors["province"] = "กรุณากรอกจังหวัด"
    elif province not in PROVINCES:
        errors["province"] = "ไม่พบจังหวัดนี้ กรุณาพิมพ์ชื่อจังหวัดให้ถูกต้อง (เลือกจากรายการที่แสดงได้)"
    clean["province"] = province

    zipcode = (form.get("zipcode") or "").strip()
    if not ZIP_RE.fullmatch(zipcode):
        errors["zipcode"] = "รหัสไปรษณีย์ต้องเป็นตัวเลข 5 หลัก"
    clean["zipcode"] = zipcode
    return clean, errors


@app.route("/checkout", methods=["GET", "POST"])
@login_required
def checkout():
    items = get_cart_items()
    if not items:
        flash("ตะกร้าสินค้าว่างอยู่")
        return redirect(url_for("cart"))
    total = sum(i["sub"] for i in items)
    # แอดมินไม่ต้องมีอีเมล; ลูกค้าที่ยังไม่มีอีเมลในบัญชี (สมัครก่อนเพิ่มช่องนี้) ต้องกรอกตอนสั่งซื้อ
    user_row = get_db().execute("SELECT * FROM users WHERE id=?", (session.get("uid"),)).fetchone()
    need_email = session.get("role") != "admin" and not (user_row and user_row["email"])
    if request.method == "POST":
        form = {k: request.form.get(k, "") for k in ("name", "phone", "addr", "subdistrict", "district", "province", "zipcode", "email")}
        clean, errors = validate_shipping(form)
        if need_email:
            new_email, email_error = validate_email(form["email"])
            if email_error:
                errors["email"] = email_error
            elif email_in_use(new_email, session.get("uid")):
                errors["email"] = "อีเมลนี้ถูกใช้โดยบัญชีอื่นแล้ว"
        if errors:
            flash("กรุณาแก้ไขข้อมูลที่ไม่ถูกต้องก่อนดำเนินการต่อ")
            return render_template("checkout.html", total=total, form=form, errors=errors, provinces=PROVINCES, need_email=need_email)
        recipient, phone = clean["name"], clean["phone"]
        address = " ".join(clean[f] for f in ("addr", "subdistrict", "district", "province", "zipcode"))
        db = get_db()
        try:
            db.execute("BEGIN IMMEDIATE")
            # Re-check stock inside the write transaction.
            current_items = []
            for it in items:
                row = db.execute("SELECT * FROM products WHERE id=?", (it["p"]["id"],)).fetchone()
                if row is None or row["stock"] < it["qty"]:
                    raise ValueError(f"สินค้า {it['p']['name']} มีไม่พอกับจำนวนที่สั่ง")
                current_items.append((dict(row), it["qty"]))
            exact_total = sum(p["price"] * qty for p, qty in current_items)
            created = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            # Insert whichever compatible column names exist in this shop.db.
            # Older versions used customer_name/payment_ref/unit_price; newer versions use
            # recipient/order_code/price. Populate both names when present.
            order_code_seed = f"PJG-{datetime.now():%Y%m%d}-{secrets.token_hex(3).upper()}"
            order_values = {
                "user_id": session["uid"], "recipient": recipient, "customer_name": recipient,
                "phone": phone, "address": address, "total": exact_total,
                "payment_status": "pending", "created_at": created,
                "order_code": order_code_seed, "payment_ref": order_code_seed,
            }
            order_columns = {r[1] for r in db.execute("PRAGMA table_info(orders)").fetchall()}
            insert_order_cols = [c for c in order_values if c in order_columns]
            if not insert_order_cols:
                raise sqlite3.OperationalError("ตาราง orders ไม่มีคอลัมน์ที่รองรับ")
            placeholders = ",".join("?" for _ in insert_order_cols)
            sql_cols = ",".join('"' + c + '"' for c in insert_order_cols)
            cur = db.execute(
                f"INSERT INTO orders ({sql_cols}) VALUES ({placeholders})",
                tuple(order_values[c] for c in insert_order_cols),
            )
            order_id = cur.lastrowid
            order_code = f"PJG-{datetime.now():%Y%m%d}-{order_id:06d}"
            for code_col in ("order_code", "payment_ref"):
                if code_col in order_columns:
                    db.execute(f'UPDATE orders SET "{code_col}"=? WHERE id=?', (order_code, order_id))
            for p, qty in current_items:
                item_values = {
                    "order_id": order_id, "product_id": p["id"], "product_name": p["name"],
                    "grade": p["grade"], "price": p["price"], "unit_price": p["price"],
                    "quantity": qty, "subtotal": p["price"] * qty,
                }
                item_columns = {r[1] for r in db.execute("PRAGMA table_info(order_items)").fetchall()}
                insert_item_cols = [c for c in item_values if c in item_columns]
                placeholders = ",".join("?" for _ in insert_item_cols)
                sql_cols = ",".join('"' + c + '"' for c in insert_item_cols)
                db.execute(
                    f"INSERT INTO order_items ({sql_cols}) VALUES ({placeholders})",
                    tuple(item_values[c] for c in insert_item_cols),
                )
                db.execute("UPDATE products SET stock=stock-? WHERE id=?", (qty, p["id"]))
            db.commit()
        except ValueError as exc:
            db.rollback()
            flash(str(exc))
            return redirect(url_for("cart"))
        except sqlite3.Error:
            db.rollback()
            flash("บันทึกคำสั่งซื้อไม่สำเร็จ กรุณาลองอีกครั้ง")
            return redirect(url_for("cart"))
        if need_email:
            try:
                db.execute("UPDATE users SET email=? WHERE id=?", (new_email, session["uid"]))
                db.commit()
            except sqlite3.Error:
                db.rollback()
        session["cart"] = {}
        return redirect(url_for("payment", order_id=order_id))
    # เติมข้อมูลจากหน้า "ข้อมูลส่วนตัว" ให้อัตโนมัติ (ถ้าเคยบันทึกไว้)
    prefill = {}
    if user_row:
        prefill = {"name": user_row["full_name"], "phone": user_row["phone"], "addr": user_row["addr"],
                   "subdistrict": user_row["subdistrict"], "district": user_row["district"],
                   "province": user_row["province"], "zipcode": user_row["zipcode"]}
    return render_template("checkout.html", total=total, form=prefill, errors={}, provinces=PROVINCES, need_email=need_email)


@app.route("/payment/<int:order_id>")
@login_required
def payment(order_id):
    order = get_db().execute("SELECT * FROM orders WHERE id=?", (order_id,)).fetchone()
    if not order:
        abort(404)
    if order["user_id"] != session["uid"] and session.get("role") != "admin":
        abort(403)
    if order["payment_status"] == "cancelled":
        flash("คำสั่งซื้อนี้ถูกยกเลิกแล้ว ไม่สามารถชำระเงินได้")
        return redirect(url_for("order_detail", order_id=order_id))
    order = dict(order)
    pp = SHOP_PAYMENT["promptpay_id"]
    qr = make_qr_data_uri(pp, order["total"])
    qr_is_static = qr is None
    if qr_is_static:
        # สำรอง: ถ้าสร้าง QR ตามยอดไม่ได้ (เช่น ยอดเป็น 0) ใช้ QR PromptPay ของร้านที่แนบไว้
        qr = STATIC_PROMPTPAY_QR_DATA_URI
    pay = {"bank": SHOP_PAYMENT["bank"], "bank_short": SHOP_PAYMENT["bank_short"],
           "promptpay_display": f"{pp[:3]}-{pp[3:6]}-{pp[6:]}"}
    return render_template("payment.html", order=order, qr_data_uri=qr, qr_is_static=qr_is_static, pay=pay,
                           payment_label=order_status_info(order)["label"])


@app.post("/payment/<int:order_id>/report")
@login_required
def report_payment(order_id):
    db = get_db()
