PROFILE_COLUMNS = ("email", "full_name", "phone", "addr", "subdistrict", "district", "province", "zipcode")


@app.route("/profile", methods=["GET", "POST"])
@login_required
def profile():
    """ข้อมูลส่วนตัวของผู้ใช้ที่ล็อกอินอยู่: อีเมล ชื่อ เบอร์โทร ที่อยู่เริ่มต้น และเปลี่ยนรหัสผ่าน"""
    db = get_db()
    row = db.execute("SELECT * FROM users WHERE id=?", (session["uid"],)).fetchone()
    if not row:
        session.clear()
        return redirect(url_for("login"))
    is_admin = row["role"] == "admin"
    if is_admin:
        return owner_profile_page(row)
    form = {k: row[k] for k in PROFILE_COLUMNS}
    errors = {}
    if request.method == "POST":
        if request.form.get("action") == "password":
            current = request.form.get("current_password", "")
            new_password = request.form.get("new_password", "")
            if not check_password_hash(row["password_hash"], current):
                flash("รหัสผ่านปัจจุบันไม่ถูกต้อง")
            elif len(new_password) < 6:
                flash("รหัสผ่านใหม่ต้องยาวอย่างน้อย 6 ตัวอักษร")
            elif new_password != request.form.get("confirm_password", ""):
                flash("รหัสผ่านใหม่ทั้งสองช่องไม่ตรงกัน")
            elif new_password == current:
                flash("รหัสผ่านใหม่ต้องไม่ซ้ำกับรหัสผ่านเดิม")
            else:
                db.execute("UPDATE users SET password_hash=? WHERE id=?", (generate_password_hash(new_password), row["id"]))
                db.commit()
                flash("เปลี่ยนรหัสผ่านเรียบร้อยแล้ว")
            return redirect(url_for("profile"))
        form = {k: request.form.get(k, "") for k in PROFILE_COLUMNS}
        clean, errors = validate_profile(form, is_admin, row["id"])
        if errors:
            flash("กรุณาแก้ไขข้อมูลที่ไม่ถูกต้อง")
        else:
            try:
                db.execute(
                    "UPDATE users SET email=?, full_name=?, phone=?, addr=?, subdistrict=?, district=?, province=?, zipcode=? WHERE id=?",
                    (clean["email"], clean["full_name"], clean["phone"], clean["addr"], clean["subdistrict"],
                     clean["district"], clean["province"], clean["zipcode"], row["id"]),
                )
                db.commit()
            except sqlite3.IntegrityError:
                db.rollback()
                errors["email"] = "อีเมลนี้ถูกใช้โดยบัญชีอื่นแล้ว"
                flash("กรุณาแก้ไขข้อมูลที่ไม่ถูกต้อง")
            else:
                flash("บันทึกข้อมูลส่วนตัวเรียบร้อยแล้ว")
                return redirect(url_for("profile"))
    return render_template("profile.html", account=row, is_admin=is_admin, form=form, errors=errors, provinces=PROVINCES)


