@app.route("/orders/<int:order_id>/receipt.pdf")
@login_required
def receipt_pdf(order_id):
    """สร้างและส่งไฟล์ PDF เป็นไฟล์ดาวน์โหลด พร้อมข้อความแจ้งเมื่อสร้างไม่สำเร็จ."""
    db = get_db()
    order_row = db.execute("SELECT * FROM orders WHERE id=?", (order_id,)).fetchone()
    if not order_row:
        abort(404)

    order = dict(order_row)
    if order.get("user_id") != session.get("uid") and session.get("role") != "admin":
        abort(403)

    # รองรับข้อมูลคำสั่งซื้อจากฐานข้อมูลรุ่นเก่าด้วย
    order["recipient"] = (order.get("recipient") or order.get("customer_name") or "-")
    order["order_code"] = (order.get("order_code") or order.get("payment_ref") or f"PJG-ORDER-{order_id:06d}")
    order["phone"] = order.get("phone") or "-"
    order["address"] = order.get("address") or "-"
    order["created_at"] = order.get("created_at") or "-"
    order["payment_status"] = order.get("payment_status") or "pending"

    rows = db.execute("SELECT * FROM order_items WHERE order_id=? ORDER BY id", (order_id,)).fetchall()
    items = []
    for row in rows:
        item = dict(row)
        # schema เก่าบางชุดใช้ unit_price แทน price
        price = item.get("price")
        if price in (None, "", 0, "0"):
            price = item.get("unit_price") or 0
        try:
            price = int(float(price or 0))
        except (TypeError, ValueError):
            price = 0
        try:
            quantity = max(0, int(float(item.get("quantity") or 0)))
        except (TypeError, ValueError):
            quantity = 0
        subtotal = item.get("subtotal")
        try:
            subtotal = int(float(subtotal)) if subtotal not in (None, "") else price * quantity
        except (TypeError, ValueError):
            subtotal = price * quantity
        item["product_name"] = item.get("product_name") or "สินค้า"
        item["price"] = price
        item["quantity"] = quantity
        item["subtotal"] = subtotal
        items.append(item)

    try:
        pdf = create_receipt_pdf(order, items)
        pdf_bytes = pdf.getvalue()
        if not pdf_bytes.startswith(b"%PDF-"):
            raise RuntimeError("ระบบสร้างไฟล์ PDF ไม่สมบูรณ์ กรุณาลองใหม่อีกครั้ง")
    except Exception as exc:
        app.logger.exception("สร้าง PDF ไม่สำเร็จสำหรับ order_id=%s", order_id)
        if isinstance(exc, RuntimeError):
            message = str(exc)
        elif isinstance(exc, ImportError):
            message = "ยังไม่ได้ติดตั้งไลบรารี PDF กรุณารันคำสั่ง py -m pip install reportlab แล้วเปิดโปรแกรมใหม่"
        else:
            message = f"สร้าง PDF ไม่สำเร็จ ({type(exc).__name__}) กรุณาตรวจข้อความ error ในหน้าต่าง Command Prompt"
        flash(message)
        return redirect(url_for("order_detail", order_id=order_id))

    filename = secure_filename(str(order["order_code"])) or f"order-{order_id}"
    # ส่ง bytes ตรง ๆ ใน response เพื่อให้เบราว์เซอร์ดาวน์โหลดได้แน่นอน
    response = app.response_class(pdf_bytes, mimetype="application/pdf", status=200)
    response.headers["Content-Disposition"] = f'attachment; filename="{filename}.pdf"'
    response.headers["Content-Length"] = str(len(pdf_bytes))
    response.headers["Cache-Control"] = "no-store"
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response


# ------------------------------------------------------------------
# ใบเสร็จชำระเงิน (PDF) — ออกได้เฉพาะคำสั่งซื้อที่แอดมินยืนยันรับเงินแล้ว
# (แยกจากเอกสาร PDF เดิม receipt_pdf ซึ่งไม่ถูกแก้ไข)
# ------------------------------------------------------------------
def thai_baht_text(amount):
    """แปลงจำนวนเงินเป็นตัวอักษรไทย เช่น 1250.50 -> หนึ่งพันสองร้อยห้าสิบบาทห้าสิบสตางค์"""
    digits = ["ศูนย์", "หนึ่ง", "สอง", "สาม", "สี่", "ห้า", "หก", "เจ็ด", "แปด", "เก้า"]
    places = ["", "สิบ", "ร้อย", "พัน", "หมื่น", "แสน"]

    def read_group(n):
        text = ""
        s = str(n)
        for i, ch in enumerate(s):
            d = int(ch)
            pos = len(s) - i - 1
            if d == 0:
                continue
            if pos == 0 and d == 1 and len(s) > 1:
                text += "เอ็ด"
            elif pos == 1 and d == 2:
                text += "ยี่สิบ"
            elif pos == 1 and d == 1:
                text += "สิบ"
            else:
                text += digits[d] + places[pos]
        return text

    def read_int(n):
        if n == 0:
            return digits[0]
        parts = []
        while n > 0:
            parts.append(n % 1000000)
            n //= 1000000
        out = ""
        for idx in range(len(parts) - 1, -1, -1):
            if parts[idx]:
                out += read_group(parts[idx]) + ("ล้าน" * idx)
        return out

    satang_total = int(round(float(amount) * 100))
    baht, satang = divmod(satang_total, 100)
    text = read_int(baht) + "บาท"
    text += (read_int(satang) + "สตางค์") if satang else "ถ้วน"
    return text


def _register_pdf_fonts():
    """ลงทะเบียนฟอนต์ไทยสำหรับ PDF คืนค่า (ชื่อฟอนต์ปกติ, ชื่อฟอนต์หนา, ตัวคูณขนาดตัวอักษร)"""
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont

    font_candidates = [
        os.path.join(BASE_DIR, "fonts", "THSarabunNew.ttf"),
        r"C:\Windows\Fonts\THSarabunNew.ttf",
        r"C:\Windows\Fonts\tahoma.ttf",
        r"C:\Windows\Fonts\LeelawUI.ttf",
        "/usr/share/fonts/truetype/tlwg/Garuda.ttf",
        "/usr/share/fonts/truetype/tlwg/Laksaman.ttf",
    ]
    bold_candidates = [
        os.path.join(BASE_DIR, "fonts", "THSarabunNew Bold.ttf"),
        r"C:\Windows\Fonts\THSarabunNew Bold.ttf",
        r"C:\Windows\Fonts\tahomabd.ttf",
        "/usr/share/fonts/truetype/tlwg/Garuda-Bold.ttf",
        "/usr/share/fonts/truetype/tlwg/Laksaman-Bold.ttf",
    ]
    found = next((p for p in font_candidates if os.path.isfile(p)), None)
    if not found:
        return "Helvetica", "Helvetica-Bold", 1.0
    try:
        pdfmetrics.registerFont(TTFont("PJThai", found))
        found_bold = next((p for p in bold_candidates if os.path.isfile(p)), found)
        pdfmetrics.registerFont(TTFont("PJThaiBold", found_bold))
    except Exception:
        return "Helvetica", "Helvetica-Bold", 1.0
    # TH Sarabun New มีตัวเล็กกว่าฟอนต์อื่น จึงขยายขนาดให้อ่านง่าย
    scale = 1.3 if "sarabun" in os.path.basename(found).lower() else 1.0
    return "PJThai", "PJThaiBold", scale


