@app.post("/admin/products/<int:pid>/delete")
@admin_required
def admin_product_delete(pid):
    p = get_product(pid) or abort(404)
    # Retain order history; product_id in past order items is intentionally not a foreign key.
    get_db().execute("DELETE FROM products WHERE id=?", (pid,))
