@app.route("/admin/orders")
@admin_required
def admin_orders():
    """หน้ารวมคำสั่งซื้อสำหรับแอดมิน พร้อมค้นหาชื่อลูกค้า เบอร์โทร ที่อยู่ และสินค้า"""
    db = get_db()
    q = request.args.get("q", "").strip()[:120]
    selected_status = request.args.get("status", "").strip()
    if selected_status not in ORDER_STATUS_SQL:
        selected_status = ""

    # สรุปสถานะทั้งหมด ไม่ขึ้นกับตัวกรองหน้าจอ
    counts = {key: 0 for key in ORDER_STATUS_LABELS}
    for row in db.execute(
        "SELECT payment_status, COALESCE(fulfillment_status, 'waiting') AS fs, COUNT(*) AS n FROM orders GROUP BY 1, 2"
    ).fetchall():
        counts[order_status_key(row["payment_status"], row["fs"])] += row["n"]
    stats = {"total": sum(counts.values()), **counts}

    clauses = []
    params = []
    if selected_status:
        clauses.append(ORDER_STATUS_SQL[selected_status])
    if q:
        like = f"%{q}%"
        clauses.append("""(
            COALESCE(o.order_code, '') LIKE ? OR
            COALESCE(o.recipient, '') LIKE ? OR
            COALESCE(o.customer_name, '') LIKE ? OR
            COALESCE(o.phone, '') LIKE ? OR
            COALESCE(o.address, '') LIKE ? OR
            COALESCE(u.username, '') LIKE ? OR
            COALESCE(u.email, '') LIKE ? OR
            EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id=o.id AND oi.product_name LIKE ?)
        )""")
        params.extend([like] * 8)
    where_sql = (" WHERE " + " AND ".join(clauses)) if clauses else ""
    rows = db.execute(
        """SELECT o.*, u.username AS customer_username, u.email AS customer_email
           FROM orders o LEFT JOIN users u ON u.id=o.user_id""" +
        where_sql + " ORDER BY o.id DESC LIMIT 500",
        params,
    ).fetchall()
    orders = [dict(row) for row in rows]

    # โหลดรายละเอียดสินค้าของคำสั่งซื้อที่แสดงอยู่ เพื่อให้แอดมินดูได้จากหน้าเดียว
    items_by_order = {}
    if orders:
        ids = [int(order["id"]) for order in orders]
        placeholders = ",".join("?" for _ in ids)
        item_rows = db.execute(
            f"""SELECT order_id, product_name, grade,
                       COALESCE(NULLIF(price, 0), unit_price, 0) AS display_price,
                       quantity,
                       COALESCE(NULLIF(subtotal, 0), COALESCE(NULLIF(price, 0), unit_price, 0) * quantity) AS display_subtotal
                FROM order_items WHERE order_id IN ({placeholders}) ORDER BY order_id DESC, id""",
            ids,
        ).fetchall()
        for row in item_rows:
            items_by_order.setdefault(int(row["order_id"]), []).append(dict(row))

    return render_template(
        "admin_orders.html", orders=orders, items_by_order=items_by_order,
        stats=stats, q=q, selected_status=selected_status,
        status_labels=ORDER_STATUS_LABELS, step_options=ORDER_STEP_OPTIONS,
        cancelled_count=counts.get("cancelled", 0),
    )



