@app.post("/admin/orders/<int:order_id>/set-status")
@admin_required
def admin_set_order_status(order_id):
    """เปลี่ยนสถานะคำสั่งซื้อจาก dropdown: รอดำเนินการ / กำลังเตรียมพัสดุ / กำลังจัดส่ง / จัดส่งสำเร็จ / ยกเลิกแล้ว
    (เตรียมพัสดุขึ้นไปต้องยืนยันรับเงินก่อน, ยกเลิกแล้วเปลี่ยนกลับไม่ได้, ยกเลิกจะคืนสต็อก)"""
    db = get_db()
    order = db.execute("SELECT * FROM orders WHERE id=?", (order_id,)).fetchone()
    if not order:
        abort(404)
    labels = dict(ORDER_STEP_OPTIONS)
    new = request.form.get("status", "")
    code = order["order_code"]
    if new not in labels:
        flash("สถานะที่เลือกไม่ถูกต้อง")
    elif order["payment_status"] == "cancelled":
        flash("คำสั่งซื้อที่ยกเลิกแล้วเปลี่ยนสถานะไม่ได้ (สต็อกถูกคืนไปแล้ว)")
    elif new == "cancelled":
        if cancel_order(order_id, ("pending", "reported", "paid")):
            extra = " (ลูกค้าโอนเงินแล้ว อย่าลืมคืนเงินให้ลูกค้า)" if order["payment_status"] in ("reported", "paid") else ""
            flash(f"ยกเลิกคำสั่งซื้อ {code} และคืนสต็อกแล้ว{extra}")
        else:
            flash("ยกเลิกคำสั่งซื้อไม่สำเร็จ กรุณาลองอีกครั้ง")
    elif order["payment_status"] != "paid":
        if new == "waiting":
            flash(f"คำสั่งซื้อ {code} ยังเป็น “รอดำเนินการ” อยู่แล้ว")
        else:
            flash(f"ต้องกด “ยืนยันรับเงิน” ก่อน จึงจะเปลี่ยนเป็น “{labels[new]}” ได้")
    else:
        db.execute("UPDATE orders SET fulfillment_status=? WHERE id=?", (new, order_id))
        db.commit()
        flash(f"อัปเดตสถานะคำสั่งซื้อ {code} เป็น “{labels[new]}” แล้ว")
    return redirect(request.referrer or url_for("admin_orders"))


@app.post("/admin/orders/<int:order_id>/cancel")
@admin_required
def admin_cancel_order(order_id):
    """แอดมินยกเลิกคำสั่งซื้อ (ได้ทุกสถานะที่ยังไม่ถูกยกเลิก) และคืนสต็อก — ถ้าลูกค้าโอนแล้วต้องคืนเงินเอง"""
    order = get_db().execute("SELECT * FROM orders WHERE id=?", (order_id,)).fetchone()
    if not order:
        abort(404)
    if order["payment_status"] == "cancelled":
        flash("คำสั่งซื้อนี้ถูกยกเลิกไปแล้ว")
    elif cancel_order(order_id, ("pending", "reported", "paid")):
        extra = " (ลูกค้าโอนเงินแล้ว อย่าลืมคืนเงินให้ลูกค้า)" if order["payment_status"] in ("reported", "paid") else ""
        flash(f"ยกเลิกคำสั่งซื้อ {order['order_code']} และคืนสต็อกแล้ว{extra}")
    else:
        flash("ยกเลิกคำสั่งซื้อไม่สำเร็จ กรุณาลองอีกครั้ง")
    return redirect(request.referrer or url_for("admin_orders"))


def delete_orders(order_ids):
    """ลบคำสั่งซื้อ (เฉพาะที่ยกเลิกแล้ว) พร้อมรายการสินค้าและไฟล์สลิป คืนค่าจำนวนที่ลบได้"""
    db = get_db()
    deleted = 0
    try:
        db.execute("BEGIN IMMEDIATE")
        for oid in order_ids:
            row = db.execute("SELECT slip_path FROM orders WHERE id=? AND payment_status='cancelled'", (oid,)).fetchone()
            if not row:
                continue
            db.execute("DELETE FROM order_items WHERE order_id=?", (oid,))
            db.execute("DELETE FROM orders WHERE id=? AND payment_status='cancelled'", (oid,))
            deleted += 1
            remove_payment_slip(row["slip_path"] or "")
        db.commit()
    except sqlite3.Error:
        db.rollback()
        return 0
    return deleted


@app.post("/admin/orders/<int:order_id>/delete")
@admin_required
def admin_delete_order(order_id):
    """ลบรายการคำสั่งซื้อที่ยกเลิกแล้วออกจากระบบ (ลบถาวร) — สถานะอื่นต้องยกเลิกก่อน เพื่อให้สต็อกถูกคืน"""
    order = get_db().execute("SELECT order_code, payment_status FROM orders WHERE id=?", (order_id,)).fetchone()
    if not order:
        abort(404)
    if order["payment_status"] != "cancelled":
        flash("ลบได้เฉพาะคำสั่งซื้อที่ยกเลิกแล้ว กรุณายกเลิกคำสั่งซื้อก่อน")
    elif delete_orders([order_id]):
        flash(f"ลบคำสั่งซื้อ {order['order_code']} ออกจากระบบแล้ว")
    else:
        flash("ลบคำสั่งซื้อไม่สำเร็จ กรุณาลองอีกครั้ง")
    return redirect(request.referrer or url_for("admin_orders"))


@app.post("/admin/orders/delete-cancelled")
@admin_required
def admin_delete_cancelled_orders():
    """ลบคำสั่งซื้อที่ยกเลิกแล้วทั้งหมดในครั้งเดียว"""
    ids = [r["id"] for r in get_db().execute("SELECT id FROM orders WHERE payment_status='cancelled'").fetchall()]
    count = delete_orders(ids) if ids else 0
    flash(f"ลบคำสั่งซื้อที่ยกเลิกแล้วทั้งหมด {count} รายการ" if count else "ไม่มีคำสั่งซื้อที่ยกเลิกให้ลบ")
    return redirect(url_for("admin_orders"))


@app.route("/admin/settings", methods=["GET", "POST"])
@admin_required
def admin_settings():
    db = get_db()
    settings = all_settings()
    info = {k: get_setting(k, "") for k in (*SHOP_INFO_TEXT, "shop_opened_date", "shop_logo")}
    errors = {}
    if request.method == "POST":
        shop_name = request.form.get("shop_name", "PJ GUNPLA").strip()[:100] or "PJ GUNPLA"
        shop_address = request.form.get("shop_address", "").strip()[:300]
        current_password = request.form.get("current_password", "")
        new_password = request.form.get("new_password", "")
        confirm_password = request.form.get("confirm_password", "")
        error = None
        new_info = dict(info)
        for key, limit in SHOP_INFO_TEXT.items():
            new_info[key] = (request.form.get(key) or "").strip().replace("\r\n", "\n")
            if len(new_info[key]) > limit:
                errors[key] = f"ยาวเกินไป (ไม่เกิน {limit} ตัวอักษร)"
        opened = (request.form.get("shop_opened_date") or "").strip()
        if opened:
            try:
                datetime.strptime(opened, "%Y-%m-%d")
            except ValueError:
                errors["shop_opened_date"] = "วันที่ไม่ถูกต้อง"
        new_info["shop_opened_date"] = opened
        logo_file = request.files.get("shop_logo")
        if logo_file and logo_file.filename and (not allowed_image(logo_file.filename) or not looks_like_image(logo_file)):
            errors["shop_logo"] = "ไฟล์ต้องเป็นรูป JPG, PNG หรือ WEBP"
            logo_file = None
        if new_password or current_password or confirm_password:
            account = db.execute("SELECT password_hash FROM users WHERE id=?", (session["uid"],)).fetchone()
            if not account or not check_password_hash(account["password_hash"], current_password):
                error = "รหัสผ่านปัจจุบันไม่ถูกต้อง จึงไม่สามารถเปลี่ยนรหัสผ่านได้"
            elif len(new_password) < 8:
                error = "รหัสผ่านใหม่ต้องมีอย่างน้อย 8 ตัวอักษร"
            elif new_password != confirm_password:
                error = "รหัสผ่านใหม่และช่องยืนยันไม่ตรงกัน"
        if error or errors:
            flash(error or "กรุณาแก้ไขข้อมูลที่ไม่ถูกต้อง")
            settings = {**settings, "shop_name": shop_name, "shop_address": shop_address}
            info = {**new_info, "shop_logo": info["shop_logo"]}
        else:
            old_logo = info["shop_logo"]
            if logo_file and logo_file.filename:
                new_info["shop_logo"] = save_uploaded_image(logo_file)
                remove_uploaded_image(old_logo)
            elif request.form.get("remove_shop_logo"):
                new_info["shop_logo"] = ""
                remove_uploaded_image(old_logo)
            for key, value in (("shop_name", shop_name), ("shop_address", shop_address), *new_info.items()):
                set_setting(key, value)
            if new_password:
                db.execute("UPDATE users SET password_hash=? WHERE id=?", (generate_password_hash(new_password), session["uid"]))
            db.commit()
            flash("บันทึกการตั้งค่าร้านแล้ว" if not new_password else "บันทึกการตั้งค่าร้านและเปลี่ยนรหัสผ่านแล้ว")
            return redirect(url_for("admin_settings"))
    return render_template("admin_settings.html", settings=settings, info=info, errors=errors, owner=OWNER_LOCKED)


