@app.route("/register", methods=["GET", "POST"])
def register():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")
        confirm = request.form.get("confirm", "")
        email, email_error = validate_email(request.form.get("email"))
        if len(username) < 3:
            flash("ชื่อผู้ใช้ต้องยาวอย่างน้อย 3 ตัวอักษร")
        elif email_error:
            flash(email_error)
        elif email_in_use(email):
            flash("อีเมลนี้ถูกใช้สมัครแล้ว")
        elif len(password) < 6:
            flash("รหัสผ่านต้องยาวอย่างน้อย 6 ตัวอักษร")
        elif password != confirm:
            flash("รหัสผ่านทั้งสองช่องไม่ตรงกัน")
        else:
            try:
                cur = get_db().execute("INSERT INTO users(username,password_hash,role,email) VALUES(?,?, 'customer', ?)",
                                       (username, generate_password_hash(password), email))
                get_db().commit()
            except sqlite3.IntegrityError:
                flash("ชื่อผู้ใช้หรืออีเมลนี้ถูกใช้แล้ว")
            else:
                session["uid"] = cur.lastrowid
                session["uname"] = username
                session["role"] = "customer"
                flash("สมัครสมาชิกสำเร็จ ยินดีต้อนรับสู่ PJ GUNPLA")
                return redirect(url_for("home"))
    return render_template("register.html")


@app.route("/login", methods=["GET", "POST"])
def login():
    nxt = request.values.get("next", "")
    if request.method == "POST":
        row = get_db().execute("SELECT * FROM users WHERE username=?", (request.form.get("username", "").strip(),)).fetchone()
        if row and check_password_hash(row["password_hash"], request.form.get("password", "")):
            wants_admin = bool(request.form.get("admin_login"))
            if wants_admin and row["role"] != "admin":
                flash("บัญชีนี้ไม่ใช่แอดมิน")
                return render_template("login.html", next=nxt)
            session["uid"] = row["id"]
            session["uname"] = row["username"]
            session["role"] = row["role"]
            if wants_admin:
                return redirect(url_for("admin_dashboard"))
            return redirect(safe_next(nxt))
        flash("ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง")
    return render_template("login.html", next=nxt)


@app.route("/logout")
def logout():
    session.clear()
    flash("ออกจากระบบแล้ว")
    return redirect(url_for("home"))


